// The Bundler adapter: the session source's bundle takes each connected gem from its connected copy.
// Vibe64 writes an untracked derived Gemfile, Gemfile.connected, that evaluates the tracked Gemfile
// with each connected gem's source replaced by `path: <connected copy>`, starts its lock,
// Gemfile.connected.lock, from the tracked Gemfile.lock so every other gem keeps its version, and
// selects it with the local Bundler setting `gemfile` (.bundle/config), which every `bundle`
// command, `bundle exec` included, honours. A launch outside `bundle` (plain
// `ruby -rbundler/setup`) must export BUNDLE_GEMFILE=Gemfile.connected itself. The swap never
// writes the Gemfile or Gemfile.lock. A path gem loads the connected copy in place, so a saved file
// is live with no watcher.
//
// Staging and Production install what the tracked Gemfile and Gemfile.lock name. On Save, `bump`
// pins the gem in the Gemfile to the version the connected copy declares and locks it there once
// its source publishes it (`bundle lock --update <gem>` against a Gemfile beside the tracked one).
import { readdir, readFile, realpath, rm } from "node:fs/promises";
import path from "node:path";
import { writeFileAtomic } from "@local/vibe64-core/server/atomicFile";
import { vibe64SharedModes } from "@local/vibe64-execution/server/hostProfile";
import { connectionError, notInEffect } from "./adapterResults.js";
import { readDerivedFile, refuseTracked, removeDerivedFiles, writeDerivedFiles } from "./derivedFiles.js";
import { existingEntry } from "./npmPackages.js";

const GEMFILE = "Gemfile";
const DERIVED_GEMFILE = "Gemfile.connected";
const DERIVED_LOCK = "Gemfile.connected.lock";
const BUNDLE_CONFIG = ".bundle/config";
const SELECTED = /^BUNDLE_GEMFILE:\s*"?Gemfile\.connected"?\s*$/mu;
const BUNDLE_TIMEOUT_MS = 15 * 60_000;
// Prints the gemspec's own name (a gemspec may read files relative to its folder).
const GEMSPEC_NAME_PROBE = "Dir.chdir(ARGV[1]) { spec = Gem::Specification.load(ARGV[0]) or abort('cannot load'); puts spec.name }";
// Run through `bundle exec` in the session source: what the app's own Bundler setup loads the gem from.
const LOAD_PROBE = `
name = ARGV.fetch(0)
require "bundler/setup"
real = ->(entry) { File.exist?(entry.to_s) ? File.realpath(entry.to_s) : entry.to_s }
puts "gemfile=#{File.basename(Bundler.default_gemfile.to_s)}"
spec = Gem.loaded_specs[name]
exit 0 unless spec
loaded = $LOAD_PATH.map { |entry| real.(entry) }
puts "source=#{spec.source.is_a?(Bundler::Source::Path) ? "path" : spec.source.class.name}"
puts "path=#{real.(spec.full_gem_path)}"
spec.full_require_paths.each { |entry| puts "#{loaded.include?(real.(entry)) ? "loads" : "unloaded"}=#{real.(entry)}" }
`;

/** A Ruby single-quoted string literal: nothing in it interpolates. */
function rubyString(text) {
  return `'${text.replace(/[\\']/gu, match => `\\${match}`)}'`;
}

function derivedGemfile(gems) {
  const paths = gems.map(entry => `${rubyString(entry.name)} => ${rubyString(entry.root)}`).join(", ");
  return `# Generated by Vibe64 for connected development. Untracked.
# Evaluates the tracked Gemfile, replacing each connected gem's source by its connected copy.
connected = { ${paths} }.freeze
declared = []
define_singleton_method(:gem) do |name, *args|
  path = connected[name]
  return super(name, *args) unless path
  declared << name
  options = args.last.is_a?(Hash) ? args.pop.dup : {}
  %i[git github gitlab bitbucket branch ref tag submodules glob source].each { |key| options.delete(key) }
  super(name, *args, options.merge(path: path))
end
eval_gemfile File.expand_path(${rubyString(GEMFILE)}, __dir__)
# A connected gem the Gemfile does not declare itself (a dependency of one it does) still comes from its copy.
(connected.keys - declared).each { |name| gem name, path: connected[name] }
`;
}

/** The gem names a lockfile lists in its specs. */
function lockedGems(lockText) {
  return new Set([...String(lockText || "").matchAll(/^ {4}([^\s(]+) \(/gmu)].map(match => match[1]));
}

function escapeRegExp(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&");
}

/** Whether a Bundler lockfile locks this gem to a path source at this root. */
function locksToPath(lockText, tree, gem) {
  return String(lockText || "").split(/\n\s*\n/u).some(section => {
    const remote = /^PATH\n {2}remote: (.+)$/mu.exec(section);
    return remote && path.resolve(tree, remote[1]) === gem.root && new RegExp(`^ {4}${escapeRegExp(gem.name)} \\(`, "mu").test(section);
  });
}

async function realRoot(connection) {
  return realpath(connection.sourceRoot).catch(() => {
    throw connectionError(connection, `its connected copy ${connection.sourceRoot} is missing.`, "vibe64_connected_bundler_copy_missing");
  });
}

/**
 * What the session's bundle must look like for every connected Bundler dependency. A connected
 * copy holds exactly one gemspec, named after its gem.
 * @param {{ connections: Array<object>, sessionSourceRoot: string }} input
 */
async function bundlerPlan({ connections, sessionSourceRoot }) {
  if (!(await existingEntry(path.join(sessionSourceRoot, GEMFILE)))?.isFile()) {
    throw connectionError(connections[0], "the session source has no Gemfile, so no bundle uses it.", "vibe64_connected_bundler_unused");
  }
  const lockText = await readDerivedFile(sessionSourceRoot, "Gemfile.lock");
  const locked = lockedGems(lockText);
  const gems = [];
  for (const connection of connections) {
    const root = await realRoot(connection);
    const gemspecs = (await readdir(root)).filter(entry => entry.endsWith(".gemspec"));
    if (gemspecs.length !== 1) {
      throw connectionError(
        connection,
        `its connected copy must hold exactly one gemspec at its root, and holds ${gemspecs.length}.`,
        "vibe64_connected_bundler_gemspec_invalid"
      );
    }
    const name = gemspecs[0].slice(0, -".gemspec".length);
    if (lockText !== null && !locked.has(name)) {
      throw connectionError(
        connection,
        `the session's Gemfile.lock does not use ${name}, so nothing would take it from the connected copy.`,
        "vibe64_connected_bundler_unused"
      );
    }
    gems.push({
      connection,
      gemspec: gemspecs[0],
      name,
      root
    });
  }
  return {
    gemfileText: derivedGemfile(gems),
    gems,
    lockText
  };
}

function planEntry(plan, connection) {
  return plan.gems.find(entry => entry.connection.repository === connection.repository);
}

function failure(result) {
  return String(result?.stderr || result?.error || "").trim().split("\n").slice(-8).join("\n");
}

/** Puts every connected Bundler dependency in effect in the session source. */
async function applyBundler({ connection, connections, sessionSourceRoot, runCommand, writeGitExcludes }) {
  const plan = await bundlerPlan({ connections, sessionSourceRoot });
  for (const gem of plan.gems) {
    const named = await runCommand({
      command: "ruby",
      args: ["-e", GEMSPEC_NAME_PROBE, path.join(gem.root, gem.gemspec), gem.root],
      cwd: sessionSourceRoot,
      timeout: 60_000
    });
    if (named?.ok !== true) {
      throw connectionError(
        gem.connection,
        `Ruby could not load ${gem.gemspec}. ${failure(named)}`.trim(),
        "vibe64_connected_bundler_gemspec_invalid"
      );
    }
    if (String(named.stdout || "").trim() !== gem.name) {
      throw connectionError(
        gem.connection,
        `${gem.gemspec} names the gem ${String(named.stdout || "").trim()}; Vibe64 needs the gemspec file named after its gem.`,
        "vibe64_connected_bundler_gemspec_invalid"
      );
    }
  }
  // Bundler writes the derived lock itself when there is no tracked one to start it from.
  await refuseTracked({
    connection,
    tree: sessionSourceRoot,
    paths: [BUNDLE_CONFIG, ...(plan.lockText === null ? [DERIVED_LOCK] : [])],
    runCommand
  });
  await writeDerivedFiles({
    connection,
    tree: sessionSourceRoot,
    files: {
      [DERIVED_GEMFILE]: plan.gemfileText,
      ...(plan.lockText === null ? {} : { [DERIVED_LOCK]: plan.lockText })
    },
    runCommand,
    writeGitExcludes
  });
  // The local setting selects the derived Gemfile, so it must never reach a commit either.
  await writeGitExcludes(sessionSourceRoot, [DERIVED_GEMFILE, DERIVED_LOCK, BUNDLE_CONFIG]);
  const selected = await runCommand({
    command: "bundle",
    args: ["config", "set", "--local", "gemfile", DERIVED_GEMFILE],
    cwd: sessionSourceRoot,
    timeout: 60_000
  });
  if (selected?.ok !== true) {
    throw connectionError(
      connection,
      `Bundler could not select ${DERIVED_GEMFILE}. ${failure(selected)}`.trim(),
      "vibe64_connected_bundler_install_failed"
    );
  }
  const installed = await runCommand({
    command: "bundle",
    args: ["install", "--quiet"],
    cwd: sessionSourceRoot,
    timeout: BUNDLE_TIMEOUT_MS,
    env: { BUNDLE_GEMFILE: path.join(sessionSourceRoot, DERIVED_GEMFILE) }
  });
  if (installed?.ok !== true) {
    throw connectionError(
      connection,
      `bundle install could not take the connected gems. ${failure(installed)}`.trim(),
      "vibe64_connected_bundler_install_failed"
    );
  }
  return { lines: [`[Connected] ${connection.name}: gem ${planEntry(plan, connection).name} in effect from its connected copy.`] };
}

function probeAnswer(stdout) {
  const answer = { loads: [], unloaded: [] };
  for (const line of String(stdout || "").split("\n")) {
    const at = line.indexOf("=");
    if (at < 0) continue;
    const [key, value] = [line.slice(0, at), line.slice(at + 1)];
    if (key === "loads" || key === "unloaded") answer[key].push(value);
    else answer[key] = value;
  }
  return answer;
}

function inside(root, candidate) {
  return candidate === root || candidate.startsWith(`${root}${path.sep}`);
}

/** Whether this connection's gem loads from its connected copy. */
async function proveBundler({ connection, connections, sessionSourceRoot, runCommand }) {
  const plan = await bundlerPlan({ connections, sessionSourceRoot });
  const own = planEntry(plan, connection);
  const gemfile = await readDerivedFile(sessionSourceRoot, DERIVED_GEMFILE);
  if (gemfile === null) {
    return notInEffect(`${DERIVED_GEMFILE} is missing; prepare the workspace to take ${own.name} from the connected copy.`);
  }
  if (gemfile !== plan.gemfileText) {
    return notInEffect(`${DERIVED_GEMFILE} no longer matches the connected copies; prepare the workspace again.`);
  }
  if (!locksToPath(await readDerivedFile(sessionSourceRoot, DERIVED_LOCK), sessionSourceRoot, own)) {
    return notInEffect(`${DERIVED_LOCK} does not lock ${own.name} to the connected copy; prepare the workspace again.`);
  }
  if (!SELECTED.test(await readDerivedFile(sessionSourceRoot, BUNDLE_CONFIG) || "")) {
    return notInEffect(`${BUNDLE_CONFIG} does not select ${DERIVED_GEMFILE}, so bundle exec uses the published ${own.name}; `
      + "prepare the workspace again.");
  }
  if (!runCommand) return { inEffect: true, reason: "" };
  const probe = await runCommand({
    command: "bundle",
    args: ["exec", "ruby", "-e", LOAD_PROBE, own.name],
    cwd: sessionSourceRoot,
    timeout: 120_000
  });
  if (probe?.ok !== true) return notInEffect(`bundle exec could not load the bundle. ${failure(probe)}`.trim());
  const answer = probeAnswer(probe.stdout);
  if (answer.gemfile !== DERIVED_GEMFILE) return notInEffect(`bundle exec uses ${answer.gemfile || "no Gemfile"}, not ${DERIVED_GEMFILE}.`);
  if (!answer.path) return notInEffect(`bundle exec does not load ${own.name}.`);
  if (answer.source !== "path" || answer.path !== own.root) {
    return notInEffect(`bundle exec loads ${own.name} from ${answer.path}, not the connected copy ${own.root}.`);
  }
  const loads = answer.loads.filter(entry => inside(own.root, entry));
  if (!loads.length || answer.unloaded.length) {
    return notInEffect(`bundle exec does not put ${own.name}'s connected lib folders on the load path.`);
  }
  return { inEffect: true, reason: "" };
}

/** Takes the gemfile setting back out of .bundle/config, leaving the project's own settings. */
async function unselectDerivedGemfile(sessionSourceRoot) {
  const configPath = path.join(sessionSourceRoot, BUNDLE_CONFIG);
  const config = await readFile(configPath, "utf8").catch(() => null);
  if (config === null || !SELECTED.test(config)) return false;
  const rest = config.split("\n").filter(line => !SELECTED.test(line)).join("\n");
  if (/^[-\s]*$/u.test(rest)) {
    await rm(configPath, { force: true });
    return true;
  }
  await writeSourceFile(configPath, rest);
  return true;
}

/** Removes the derived Gemfile, its lock and the setting selecting it once no Bundler connection remains. */
async function restoreBundler({ connections, sessionSourceRoot, writeGitExcludes }) {
  if (connections.length) return [];
  const unselected = await unselectDerivedGemfile(sessionSourceRoot);
  const paths = [];
  for (const relative of [DERIVED_GEMFILE, DERIVED_LOCK]) {
    if (await existingEntry(path.join(sessionSourceRoot, relative))) paths.push(relative);
  }
  // A session that never had a Bundler connection is left exactly as it is.
  if (!unselected && !paths.length) return [];
  const removed = await removeDerivedFiles({
    tree: sessionSourceRoot,
    paths,
    writeGitExcludes
  });
  return [`[Connected] bundler: removed ${[...removed, ...(unselected ? [`the gemfile setting in ${BUNDLE_CONFIG}`] : [])].join(", ")}.`];
}

const BUMP_GEMFILE = "Gemfile.vibe64-bump";

/** The version a gemspec declares, read from files: a literal `version =`, else lib/<gem>/version.rb. */
async function declaredVersion(root, gemspec, name) {
  const spec = await readFile(path.join(root, gemspec), "utf8").catch(() => "");
  const literal = /\.version\s*=\s*["']([^"']+)["']/u.exec(spec);
  if (literal) return literal[1];
  const versionFile = await readFile(path.join(root, "lib", ...name.split("-"), "version.rb"), "utf8").catch(() => "");
  return /VERSION\s*=\s*["']([^"']+)["']/u.exec(versionFile)?.[1] || null;
}

/** The version a lockfile holds for a gem, without its platform. */
function lockedVersion(lockText, name) {
  const match = new RegExp(`^ {4}${escapeRegExp(name)} \\(([^)]+)\\)`, "mu").exec(String(lockText || ""));
  return match ? match[1].split("-")[0] : null;
}

/**
 * The version the connected copy declares and the one the tracked Gemfile.lock (what Staging and
 * Production install) holds, for this connection's gem when the project uses it. Reads files only.
 */
async function lockedBundler({ connection, sessionSourceRoot }) {
  const root = await realRoot(connection);
  const gemspecs = (await readdir(root)).filter(entry => entry.endsWith(".gemspec"));
  if (gemspecs.length !== 1) return [];
  const name = gemspecs[0].slice(0, -".gemspec".length);
  const lockText = await readDerivedFile(sessionSourceRoot, "Gemfile.lock");
  if (lockText !== null && !lockedGems(lockText).has(name)) return [];
  return [{
    package: name,
    connected: await declaredVersion(root, gemspecs[0], name),
    locked: lockedVersion(lockText, name)
  }];
}

/** The Gemfile with the gem's own declaration pinned to exactly this version, or null when it declares none. */
function pinnedGemfile(gemfile, name, version) {
  const declaration = new RegExp(`^(\\s*gem\\s*\\(?\\s*["']${escapeRegExp(name)}["'])((?:\\s*,\\s*["'][^"'\\n]*["'])*)`, "mu");
  return declaration.test(gemfile) ? gemfile.replace(declaration, `$1, "${version}"`) : null;
}

async function writeSourceFile(filePath, text) {
  const modes = vibe64SharedModes();
  await writeFileAtomic(filePath, text, { directoryMode: modes.inheritingDirectory, fileMode: modes.file });
}

/**
 * Locks one gem at a version through Bundler, against a copy of the Gemfile beside the tracked one
 * (so its relative paths hold) that never reads the derived Gemfile. Resolves to the new Gemfile.lock,
 * or { unpublished } / { failed } when Bundler cannot.
 */
async function lockAt({ sessionSourceRoot, runCommand, gemfile, lockText, name, version }) {
  const bumpGemfile = path.join(sessionSourceRoot, BUMP_GEMFILE);
  try {
    await writeSourceFile(bumpGemfile, gemfile);
    if (lockText !== null) await writeSourceFile(`${bumpGemfile}.lock`, lockText);
    const locked = await runCommand({
      command: "bundle",
      args: ["lock", "--update", name],
      cwd: sessionSourceRoot,
      timeout: BUNDLE_TIMEOUT_MS,
      env: { BUNDLE_GEMFILE: bumpGemfile }
    });
    if (locked?.ok !== true) {
      const said = `${locked?.stderr || ""}\n${locked?.stdout || ""}`;
      return /Could not find gem/u.test(said) ? { unpublished: true } : { failed: failure(locked) || "bundle lock failed" };
    }
    const newLock = await readFile(`${bumpGemfile}.lock`, "utf8");
    return lockedVersion(newLock, name) === version ? { newLock } : { failed: `bundle lock locked ${lockedVersion(newLock, name)}` };
  } finally {
    await rm(bumpGemfile, { force: true });
    await rm(`${bumpGemfile}.lock`, { force: true });
  }
}

/**
 * On Save: pins the connected gem in the tracked Gemfile and Gemfile.lock to the version the connected
 * copy declares once its source publishes it, then puts the connection in effect again on top.
 */
async function bumpBundler(context) {
  const { connection, sessionSourceRoot, runCommand } = context;
  const bumped = [];
  const lines = [];
  for (const entry of await lockedBundler(context)) {
    if (!entry.connected || entry.connected === entry.locked) continue;
    const gemfile = await readFile(path.join(sessionSourceRoot, GEMFILE), "utf8");
    const pinned = pinnedGemfile(gemfile, entry.package, entry.connected);
    if (pinned === null) {
      lines.push(`[Connected] ${connection.name}: the Gemfile does not declare ${entry.package} itself, `
        + `so Vibe64 leaves its locked ${entry.locked}.`);
      continue;
    }
    const result = await lockAt({
      sessionSourceRoot,
      runCommand,
      gemfile: pinned,
      lockText: await readDerivedFile(sessionSourceRoot, "Gemfile.lock"),
      name: entry.package,
      version: entry.connected
    });
    if (result.unpublished) continue;
    if (result.failed) {
      lines.push(`[Connected] ${connection.name}: could not check whether ${entry.package} ${entry.connected} is published: `
        + `${result.failed.replace(/\.$/u, "")}.`);
      continue;
    }
    await writeSourceFile(path.join(sessionSourceRoot, GEMFILE), pinned);
    await writeSourceFile(path.join(sessionSourceRoot, "Gemfile.lock"), result.newLock);
    bumped.push({
      package: entry.package,
      from: entry.locked,
      to: entry.connected
    });
    lines.push(`[Connected] ${connection.name}: Staging and Production now use the published ${entry.package} ${entry.connected}.`);
  }
  // The derived lock starts from the tracked one, which just moved.
  if (bumped.length) lines.push(...(await applyBundler(context)).lines);
  return { bumped, lines };
}

const bundlerAdapter = Object.freeze({
  type: "bundler",
  runtimeRequirements: Object.freeze(["ruby", "git"]),
  apply: applyBundler,
  proof: proveBundler,
  restore: restoreBundler,
  locked: lockedBundler,
  bump: bumpBundler
});

export { bundlerAdapter };
